/bin/bash -lc "node --input-type=module <<'EOF'
import { processJob, retriesEnabled } from './src/worker.js';
const events=[];
await processJob({id:'j1', execute:async()=>{events.push('execute'); return 'ok';}}, {ack:async()=>events.push('ack')}, {record:async()=>events.push('record')});
console.log('process order:', events.join(' -> '));
console.log('RETRIES_ENABLED=false:', retriesEnabled({RETRIES_ENABLED:'false'}));
EOF
printf '%s\\n' '---MIGRATION STATIC CHECK---'
awk 'NR<=20 {print NR \":\" "'$0}'"' migrations/007_reset_job_keys.sql
printf '%s\\n' '---MAIN PRESENCE---'
if test -e src/main.js; then echo present; else echo 'src/main.js absent'; fi"

